<?php
namespace Tests\Unit;
use App\Services\Trading\SelectedProposalService;
use Tests\TestCase;
class SelectedProposalServiceTest extends TestCase
{public function test_empty_and_entry_selected_proposal():void{$svc=new SelectedProposalService();$this->assertSame('unavailable',$svc->build([])['status']);$eval=['status'=>'eligible_for_reference_selection','selection_scope'=>'entry_candidate_reference','policy_id'=>'p','policy_version'=>'v','portfolio_id'=>'pf'];$r=$svc->build(['decision_at'=>'2026-07-01','policy_evaluation'=>$eval,'action_candidate'=>['candidate_id'=>'c','ticker'=>'BUMI'],'portfolio_approval'=>['schema_version'=>'portfolio_approval_v1','status'=>'approved_reference','approval_id'=>'a'],'reference_quantity'=>5000]);$this->assertSame('selected_reference',$r['status']);$this->assertSame('long_entry',$r['proposal_type']);$this->assertFalse($r['selection_result']['production_selected']);$this->assertFalse($r['execution']['executable']);$this->assertNull($r['execution']['instruction']);$this->assertNotContains($r['proposal_type'],['BUY','SELL','HOLD','CUT_LOSS']);}
 public function test_management_exit_reduction_and_deterministic_identity():void{$svc=new SelectedProposalService();$eval=['status'=>'eligible_for_reference_selection','selection_scope'=>'management_action_reference','policy_id'=>'p','policy_version'=>'v','portfolio_id'=>'pf','position_id'=>'pos','management_candidate_id'=>'mc','action_plan_id'=>'plan','proposed_management_action'=>'exit_position','proposed_quantity_reference'=>1000];$ctx=['decision_at'=>'2026-07-01','policy_evaluation'=>$eval,'action_plan'=>['position_id'=>'pos','action_plan_id'=>'plan','proposed_management_action'=>'exit_position','quantity_plan'=>['proposed_quantity_reference'=>1000,'remaining_quantity_reference'=>0]],'management_portfolio_approval'=>['schema_version'=>'mpa','status'=>'approved_reference','approval_id'=>'ma']];$a=$svc->build($ctx);$b=$svc->build($ctx);$this->assertSame($a['selected_proposal_id'],$b['selected_proposal_id']);$this->assertSame('exit_position',$a['proposal_type']);$ctx['action_plan']['quantity_plan']['proposed_quantity_reference']=500;$ctx['policy_evaluation']['proposed_quantity_reference']=500;$c=$svc->build($ctx);$this->assertNotSame($a['selected_proposal_id'],$c['selected_proposal_id']);}}
